<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('inventory.low_stock');$rows=db()->query('SELECT p.id,p.name,p.sku,p.current_stock,p.minimum_stock,p.average_cost,u.short_name,c.name category_name FROM products p INNER JOIN units u ON u.id=p.unit_id INNER JOIN categories c ON c.id=p.category_id WHERE p.status="active" AND p.track_stock=1 AND p.current_stock<=p.minimum_stock ORDER BY (p.current_stock<=0) DESC,p.current_stock ASC,p.name')->fetchAll();$pageTitle='Low Stock';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('inventory/index.php'))?>">← Inventory</a><h2>Low-stock alerts</h2><p>Products at or below their configured minimum stock level.</p></div><?php if(user_can('purchases.create')):?><a class="button button--primary" href="<?=e(app_url('purchases/add.php'))?>">Create purchase</a><?php endif;?></div><section class="panel-card table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Current</th><th>Minimum</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state"><strong>Stock levels look good</strong><span>No products are currently at their alert level.</span></div></td></tr><?php else:foreach($rows as$r):?><tr><td><strong><?=e($r['name'])?></strong><small class="table-note"><?=e($r['sku'])?></small></td><td><?=e($r['category_name'])?></td><td><?=e(format_quantity($r['current_stock']))?> <?=e($r['short_name'])?></td><td><?=e(format_quantity($r['minimum_stock']))?> <?=e($r['short_name'])?></td><td><span class="status-badge status-badge--locked"><?= (float)$r['current_stock']<=0?'Out of stock':'Low stock'?></span></td><td class="table-action-cell"><a class="table-action" href="<?=e(app_url('products/view.php?id='.(int)$r['id']))?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
